	_, err := s.db.ExecContext(ctx, `INSERT INTO events (task_id,actor_id,event_type,payload_json,created_at) VALUES (?,?,?,?,?)`,
		taskID, actorID, typ, string(b), ts(time.Now().UTC()))
	return err
}

