+function h(tag, attrs = {}, ...children) {
+  const el = document.createElement(tag);
+  for (const [k, v] of Object.entries(attrs || {})) {
+    if (k === "class") el.className = v;
+    else if (k.startsWith("on")) el.addEventListener(k.slice(2).toLowerCase(), v);
+    else if (v !== undefined && v !== null) el.setAttribute(k, v);
+  }
+  for (const child of children.flat()) {
+    if (child === undefined || child === null) continue;
+    el.append(child.nodeType ? child : document.createTextNode(String(child)));
+  }
+  return el;
+}
+
+async function api(path, options = {}) {
+  const res = await fetch(path, {
+    ...options,
+    headers: {
+      "Content-Type": "application/json",
+      "Authorization": `Bearer ${apiState.token}`,
+      "X-Actor-ID": apiState.actor,
+      ...(options.headers || {}),
+    },
+  });
+  const data = await res.json().catch(() => ({}));
+  if (!res.ok) throw new Error(data.message || data.error || res.statusText);
+  return data;
+}
+
+async function refresh() {
+  try {
+    apiState.error = "";
+    const [tasks, actors, handoffs, events] = await Promise.all([
+      api("/api/tasks"),
+      api("/api/actors"),
+      api("/api/handoffs"),
+      api("/api/events"),
+    ]);
+    apiState.tasks = tasks;
+    apiState.actors = actors;
+    apiState.handoffs = handoffs;
+    apiState.events = events;
+    if (apiState.selected) apiState.detail = await api(`/api/tasks/${apiState.selected}`);
