	since, _ := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
	out, err := s.store.ListEvents(r.Context(), since, "")
	writeResult(w, out, err)
}

func decode(w http.ResponseWriter, r *http.Request, out any) bool {
	if err := json.NewDecoder(r.Body).Decode(out); err != nil {
		writeErr(w, http.StatusBadRequest, userErr("bad_request", "invalid JSON body"))
		return false
	}
	return true
}

func writeResult(w http.ResponseWriter, out any, err error) {
	if err != nil {
		status := http.StatusInternalServerError
		switch errorCode(err) {
		case "validation", "bad_request":
			status = http.StatusBadRequest
		case "unauthorized":
			status = http.StatusUnauthorized
		case "forbidden":
			status = http.StatusForbidden
		case "not_found":
			status = http.StatusNotFound
		case "conflict":
			status = http.StatusConflict
		}
		writeErr(w, status, err)
		return
	}
	writeJSON(w, http.StatusOK, out)
}

func writeErr(w http.ResponseWriter, status int, err error) {
	var pe publicError
	code := "internal"
	msg := "internal server error"
	if errors.As(err, &pe) {
		code = pe.code
		msg = pe.msg
	} else if err != nil {
		msg = err.Error()
	}
	writeJSON(w, status, APIError{Error: code, Message: msg})
}

func writeJSON(w http.ResponseWriter, status int, out any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(out)
}

func ListenAndServe(addr, dbPath, token string) error {
	store, err := OpenStore(dbPath)
	if err != nil {
		return err
	}
	defer store.Close()
	fmt.Printf("TaskPilot server listening on http://%s\n", addr)
	fmt.Printf("Team token: %s\n", token)
	return http.ListenAndServe(addr, NewServer(store, token))
}

:root {
  color-scheme: light;
  --bg: #f6f7f9;
  --panel: #ffffff;
  --line: #d7dce2;
  --text: #1e242c;
  --muted: #637083;
  --blue: #2563eb;
  --green: #0f766e;
  --red: #b42318;
  --amber: #b45309;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.45 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
button, input, select, textarea {
  font: inherit;
}
button {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--text);
  min-height: 34px;
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
}
button.primary { background: var(--blue); color: #fff; border-color: var(--blue); }
button.danger { color: var(--red); }
input, select, textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--text);
  border-radius: 6px;
  padding: 8px;
}
textarea { min-height: 76px; resize: vertical; }
.shell { min-height: 100vh; display: grid; grid-template-rows: auto 1fr; }
.topbar {
  height: 58px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 18px;
  background: #fff;
  border-bottom: 1px solid var(--line);
}
.brand { font-weight: 700; font-size: 18px; }
.tabs { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.tabs button.active { border-color: var(--blue); color: var(--blue); }
.main { padding: 18px; display: grid; gap: 16px; }
.stats { display: grid; grid-template-columns: repeat(5, minmax(120px, 1fr)); gap: 10px; }
.stat {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
}
.stat strong { display: block; font-size: 22px; }
.board { display: grid; grid-template-columns: repeat(7, minmax(180px, 1fr)); gap: 10px; overflow-x: auto; }
.column {
  min-height: 360px;
  background: #eef1f5;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px;
}
.column h3 { margin: 2px 2px 8px; font-size: 13px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  margin-bottom: 8px;
  cursor: pointer;
}
.card:hover { border-color: #9aa7b6; }
.card-title { font-weight: 650; margin-bottom: 6px; }
.meta { color: var(--muted); font-size: 12px; display: grid; gap: 2px; }
.pill {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px 7px;
  font-size: 12px;
  color: var(--muted);
}
.pill.red { color: var(--red); border-color: #fecaca; background: #fff5f5; }
.pill.amber { color: var(--amber); border-color: #fed7aa; background: #fff7ed; }
.grid2 { display: grid; grid-template-columns: 360px 1fr; gap: 16px; align-items: start; }
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
}
.panel h2, .panel h3 { margin: 0 0 12px; }
.form { display: grid; gap: 10px; }
.row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.detail { display: grid; gap: 12px; }
.section { border-top: 1px solid var(--line); padding-top: 12px; }
.timeline { display: grid; gap: 8px; }
.event { border-left: 3px solid var(--line); padding-left: 10px; color: var(--muted); }
.list { display: grid; gap: 8px; }
.item {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  background: #fff;
}
.error { color: var(--red); }
@media (max-width: 900px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .grid2 { grid-template-columns: 1fr; }
}

