func TestLockConflictAndRelease(t *testing.T) {
	ctx := context.Background()
	s := testStore(t)
	a := testActor(t, s, "Agent A")
	b := testActor(t, s, "Agent B")
	task, err := s.CreateTask(ctx, a.ID, TaskInput{Title: "Task", Goal: "Goal"})
