      h("div", { class: "row" }, noteKind, h("button", { onclick: async () => { await api(`/api/tasks/${task.id}/context`, { method: "POST", body: JSON.stringify({ kind: noteKind.value, content: note.value }) }); note.value = ""; await refresh(); } }, "Add Context")),
