  if (!res.ok) {
    const err = new Error(data.message || data.error || res.statusText);
    err.status = res.status;
    throw err;
  }
  return data;
}

async function refresh() {
  try {
    apiState.error = "";
    await ensureActor();
    const [tasks, actors, handoffs, events] = await Promise.all([
      api("/api/tasks"),
      api("/api/actors"),
      api("/api/handoffs"),
      api("/api/events"),
    ]);
    apiState.tasks = tasks;
    apiState.actors = actors;
    apiState.handoffs = handoffs;
    apiState.events = events;
    if (apiState.selected) apiState.detail = await api(`/api/tasks/${apiState.selected}`);
  } catch (err) {
    apiState.error = err.message;
  }
  render();
}

