	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync/atomic"
	"time"
)

type serverMetrics struct {
	Requests uint64 `json:"requests"`
	Errors   uint64 `json:"errors"`
	Started  string `json:"started_at"`
}

type responseRecorder struct {
	http.ResponseWriter
	status int
}

func (r *responseRecorder) WriteHeader(status int) {
	r.status = status
	r.ResponseWriter.WriteHeader(status)
}

func (r *responseRecorder) Write(b []byte) (int, error) {
	if r.status == 0 {
		r.status = http.StatusOK
	}
	return r.ResponseWriter.Write(b)
}

func (s *Server) middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		requestID := r.Header.Get("X-Request-ID")
		if requestID == "" {
			requestID = newRequestID()
		}
		w.Header().Set("X-Request-ID", requestID)
		applySecurityHeaders(w)
		if r.Body != nil {
			r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		}
		rec := &responseRecorder{ResponseWriter: w}
		atomic.AddUint64(&s.metrics.Requests, 1)
		next.ServeHTTP(rec, r)
		if rec.status >= 500 {
			atomic.AddUint64(&s.metrics.Errors, 1)
		}
		log.Printf("request_id=%s method=%s path=%s status=%d duration_ms=%d", requestID, r.Method, r.URL.Path, rec.status, time.Since(start).Milliseconds())
	})
}

func applySecurityHeaders(w http.ResponseWriter) {
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'")
}

func newRequestID() string {
	var b [8]byte
	if _, err := rand.Read(b[:]); err == nil {
		return hex.EncodeToString(b[:])
	}
	return strconv.FormatInt(time.Now().UnixNano(), 36)
}

func metricsText(m serverMetrics, counts StoreStats) string {
	lines := []string{
		"# HELP taskpilot_requests_total Total HTTP requests.",
		"# TYPE taskpilot_requests_total counter",
		fmt.Sprintf("taskpilot_requests_total %d", m.Requests),
		"# HELP taskpilot_errors_total Total HTTP 5xx responses.",
		"# TYPE taskpilot_errors_total counter",
		fmt.Sprintf("taskpilot_errors_total %d", m.Errors),
		fmt.Sprintf("taskpilot_tasks_total %d", counts.Tasks),
		fmt.Sprintf("taskpilot_active_locks_total %d", counts.ActiveLocks),
		fmt.Sprintf("taskpilot_handoffs_total %d", counts.Handoffs),
	}
	return strings.Join(lines, "\n") + "\n"
}

package taskpilot

import (
	"fmt"
	"net"
	"os"
	"strings"
	"time"
)

type ServerConfig struct {
	Addr        string
	DBPath      string
	Token       string
	SecretKey   string
	BaseURL     string
	ArtifactDir string
	Production  bool
}

func LoadServerConfig(addrFlag, dbFlag, tokenFlag string, production bool) ServerConfig {
	addr := firstNonEmpty(addrFlag, os.Getenv("TASKPILOT_HTTP_ADDR"), "127.0.0.1:8080")
	db := firstNonEmpty(os.Getenv("TASKPILOT_DB_URL"), dbFlag, "taskpilot.db")
	token := firstNonEmpty(tokenFlag, os.Getenv("TASKPILOT_TOKEN"), "dev-token")
	return ServerConfig{
		Addr:        addr,
		DBPath:      db,
		Token:       token,
		SecretKey:   os.Getenv("TASKPILOT_SECRET_KEY"),
		BaseURL:     os.Getenv("TASKPILOT_BASE_URL"),
		ArtifactDir: firstNonEmpty(os.Getenv("TASKPILOT_ARTIFACT_DIR"), "artifacts"),
		Production:  production || strings.EqualFold(os.Getenv("TASKPILOT_ENV"), "production"),
	}
}

func (c ServerConfig) Validate() error {
	host, _, _ := net.SplitHostPort(c.Addr)
	exposed := host != "" && host != "127.0.0.1" && host != "localhost" && host != "::1"
	if c.Token == "" || c.Token == "dev-token" {
		if exposed || c.Production {
			return userErr("validation", "refusing to expose server with default token; set TASKPILOT_TOKEN or pass --token with a strong value")
		}
	}
	if c.Production && len(c.SecretKey) < 32 {
		return userErr("validation", "production mode requires TASKPILOT_SECRET_KEY with at least 32 characters")
	}
	if strings.HasPrefix(c.DBPath, "postgres://") || strings.HasPrefix(c.DBPath, "postgresql://") {
		return userErr("validation", "Postgres support is planned but not active in this binary yet; use SQLite TASKPILOT_DB_URL until the Postgres repository lands")
	}
	return nil
}

func (c ServerConfig) EffectiveBaseURL() string {
	if c.BaseURL != "" {
		return c.BaseURL
	}
	return fmt.Sprintf("http://%s", c.Addr)
}

func firstNonEmpty(values ...string) string {
	for _, v := range values {
		if v != "" {
			return v
		}
	}
	return ""
}

func heartbeatInterval() time.Duration {
	if v := os.Getenv("TASKPILOT_HEARTBEAT_INTERVAL"); v != "" {
		if d, err := time.ParseDuration(v); err == nil && d > 0 {
			return d
		}
	}
	return 5 * time.Minute
}

