+async function apiRequest(path, options = {}, includeActor = true) {
+  const res = await fetch(path, {
+    credentials: "same-origin",
+    ...options,
+    headers: { ...authHeaders(includeActor), ...(options.headers || {}) },
+  });
+  const data = await res.json().catch(() => ({}));
+  if (!res.ok) {
