func (s *Server) authPrincipal(r *http.Request) (Principal, bool) {
	auth := r.Header.Get("Authorization")
	if strings.HasPrefix(auth, "ApiKey ") {
		p, err := s.store.VerifyAPIKey(r.Context(), strings.TrimPrefix(auth, "ApiKey "))
