	for _, want := range []string{"Touched files detected", "Newly changed during run:", "- auth/new.go", "Already changed before", "- auth/old.go"} {
		if !strings.Contains(summary, want) {
			t.Fatalf("summary missing %q:\n%s", want, summary)
		}
	}
}

