+
+func createsDependencyCycle(ctx context.Context, s *Store, taskID, dependsOnID string) bool {
+	stack := []string{dependsOnID}
+	seen := map[string]bool{}
+	for len(stack) > 0 {
+		current := stack[len(stack)-1]
+		stack = stack[:len(stack)-1]
+		if current == taskID {
+			return true
+		}
+		if seen[current] {
+			continue
+		}
