+		rows, err := s.db.QueryContext(ctx, `SELECT depends_on_id FROM task_dependencies WHERE task_id=?`, current)
+		if err != nil {
+			continue
+		}
+		for rows.Next() {
+			var next string
+			if rows.Scan(&next) == nil {
