func (s *Store) listTaskDependencyRows(ctx context.Context, where, id string, includeDependsOn bool) ([]TaskDependency, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT id,task_id,depends_on_id,created_by,created_at FROM task_dependencies `+where+` ORDER BY created_at DESC`, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []TaskDependency{}
	for rows.Next() {
		var dep TaskDependency
		var created string
		if err := rows.Scan(&dep.ID, &dep.TaskID, &dep.DependsOnID, &dep.CreatedBy, &created); err != nil {
			return nil, err
		}
		dep.CreatedAt = parseTS(created)
		targetID := dep.TaskID
		if includeDependsOn {
			targetID = dep.DependsOnID
		}
		if t, err := s.GetTask(ctx, targetID); err == nil {
			dep.DependsOnTask = &t
		}
		out = append(out, dep)
	}
	return out, rows.Err()
}

