			_ = request("POST", "/api/tasks/"+taskID+"/heartbeat", map[string]any{}, &out)
		}
	}
}

func progressLoop(ctx context.Context, taskID string, interval time.Duration, done <-chan struct{}) {
	if interval <= 0 {
		return
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-done:
			return
		case <-ticker.C:
			_ = appendRunContext(taskID, "note", "taskpilot run is still active; heartbeat renewed and child command is still running.")
		}
	}
}

func createRunContextFile(taskID string) (string, func(), error) {
	f, err := os.CreateTemp("", "taskpilot-"+taskID+"-context-*.log")
	if err != nil {
		return "", nil, err
	}
	path := f.Name()
	if err := f.Close(); err != nil {
		return "", nil, err
	}
	return path, func() { _ = os.Remove(path) }, nil
}

func importRunContext(taskID, path string) int {
	entries := readRunContextFile(path)
	imported := 0
	for _, entry := range entries {
		if appendRunContext(taskID, entry.Kind, entry.Content) == nil {
			imported++
		}
	}
	return imported
}

