+	}
+	taskPath, taskCleanup, err := createJSONTemp("taskpilot-"+taskID+"-task-*.json", taskSnapshot)
+	if err != nil {
+		return "", "", nil, err
+	}
+	relatedPath, relatedCleanup, err := createJSONTemp("taskpilot-"+taskID+"-related-*.json", relatedSnapshot)
+	if err != nil {
+		taskCleanup()
