func importRunContextSince(taskID, path string, offset *int64) int {
	entries, next := readRunContextFileSince(path, *offset)
	*offset = next
	imported := 0
	for _, entry := range entries {
		if appendRunContext(taskID, entry.Kind, entry.Content) == nil {
			imported++
		}
	}
	return imported
