		return Handoff{}, err
	}
	_ = s.addEvent(ctx, h.TaskID, actorID, "lock.transferred", map[string]any{"from_actor_id": h.FromActorID, "to_actor_id": actorID})
	return h, s.addEvent(ctx, h.TaskID, actorID, "handoff.accepted", h)
}

