	_, err = s.exec(ctx, `UPDATE tasks SET owner_id='',status=?,updated_at=?,last_heartbeat_at=NULL,claim_expires_at=NULL WHERE id=?`, t.Status, ts(t.UpdatedAt), t.ID)
