		ID:                newID("conflict"),
		TaskID:            in.TaskID,
		ActorID:           in.ActorID,
		ConflictType:      in.ConflictType,
		Status:            "open",
		Scope:             strings.TrimSpace(in.Scope),
		ScopeType:         in.ScopeType,
		CurrentOwnerID:    in.CurrentOwnerID,
		OtherActorID:      in.OtherActorID,
		OtherTaskID:       in.OtherTaskID,
