		status = "draft"
	}
	if !oneOf(status, "draft", "ready", "accepted", "archived") {
		return HandoffPacket{}, userErr("validation", "invalid handoff packet status")
	}
	detail, err := s.TaskDetail(ctx, taskID)
	if err != nil {
		return HandoffPacket{}, err
	}
	snapshots := detail.Snapshots
	if len(snapshots) == 0 {
		if snapshot, err := s.CreateContextSnapshot(ctx, actorID, taskID, "final"); err == nil {
			snapshots = []ContextSnapshot{snapshot}
		}
	}
	packetContent, sourceSnapshotIDs, sourceContextIDs := buildHandoffPacketContent(detail, snapshots)
	markdown := renderHandoffMarkdown(packetContent)
	now := time.Now().UTC()
	out := HandoffPacket{
		ID:                newID("packet"),
		TaskID:            taskID,
		HandoffID:         handoffID,
		GeneratedBy:       actorID,
		Status:            status,
		Packet:            packetContent,
		Markdown:          markdown,
		SourceSnapshotIDs: sourceSnapshotIDs,
		SourceContextIDs:  sourceContextIDs,
		CreatedAt:         now,
		UpdatedAt:         now,
	}
	_, err = s.exec(ctx, `INSERT INTO handoff_packets (id,task_id,handoff_id,generated_by,status,packet_json,markdown_cache,source_snapshot_ids_json,source_context_ids_json,edited_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,
		out.ID, out.TaskID, nullableString(out.HandoffID), out.GeneratedBy, out.Status, js(out.Packet), out.Markdown, js(out.SourceSnapshotIDs), js(out.SourceContextIDs), nil, ts(out.CreatedAt), ts(out.UpdatedAt))
	if err != nil {
		return HandoffPacket{}, err
	}
	return out, s.addEvent(ctx, taskID, actorID, "handoff.packet_generated", out)
}

func (s *Store) LatestHandoffPacket(ctx context.Context, taskID string) (*HandoffPacket, error) {
	row := s.queryRow(ctx, `SELECT id,task_id,handoff_id,generated_by,status,packet_json,markdown_cache,source_snapshot_ids_json,source_context_ids_json,edited_by,created_at,updated_at FROM handoff_packets WHERE task_id=? ORDER BY updated_at DESC LIMIT 1`, taskID)
	packet, err := scanHandoffPacket(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &packet, nil
}

func (s *Store) UpdateHandoffPacketMarkdown(ctx context.Context, actorID, packetID, markdown string) (HandoffPacket, error) {
	packet, err := s.getHandoffPacket(ctx, packetID)
	if err != nil {
		return HandoffPacket{}, err
	}
	packet.Packet = parseHandoffMarkdown(markdown)
	packet.Markdown = renderHandoffMarkdown(packet.Packet)
	packet.EditedBy = actorID
	packet.UpdatedAt = time.Now().UTC()
	_, err = s.exec(ctx, `UPDATE handoff_packets SET packet_json=?,markdown_cache=?,edited_by=?,updated_at=? WHERE id=?`, js(packet.Packet), packet.Markdown, actorID, ts(packet.UpdatedAt), packet.ID)
	if err != nil {
		return HandoffPacket{}, err
	}
	return packet, s.addEvent(ctx, packet.TaskID, actorID, "handoff.packet_edited", map[string]any{"id": packet.ID})
}

