			_, _ = prepareRunHandoff(taskID, *handoffTo, err.Error(), changed, imported)
		}
		_, _ = fmt.Fprintf(os.Stderr, "Task returned to claimed state. Review context, mark blocked, or publish a handoff if needed.\n")
