+func checkpointTimelineBlock(checkpoint HandoffCheckpoint) string {
+	lines := []string{fmt.Sprintf("Checkpoint %d · %s · %s", checkpoint.Sequence, checkpoint.ActorID, checkpoint.CreatedAt.Format(time.RFC3339))}
