func heartbeatLoop(ctx context.Context, taskID string, done <-chan struct{}) {
	ticker := time.NewTicker(heartbeatInterval())
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-done:
			return
		case <-ticker.C:
			var out Task
			_ = request("POST", "/api/tasks/"+taskID+"/heartbeat", map[string]any{}, &out)
		}
	}
}

func progressLoop(ctx context.Context, taskID, contextPath string, contextOffset *int64, handoffPacketID, sessionID, handoffPath string, lastHandoffHash *string, interval time.Duration, done <-chan struct{}, mu *sync.Mutex) {
	if interval <= 0 {
		return
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-done:
			return
		case <-ticker.C:
			mu.Lock()
			_ = importRunContextSince(taskID, contextPath, contextOffset)
			_ = checkpointRunHandoffIfChanged(taskID, handoffPacketID, sessionID, handoffPath, lastHandoffHash, false)
			mu.Unlock()
		}
	}
}

