  const note = h("textarea", { placeholder: "Resolution note required" });
  return h("div", { class: "item conflict-card" },
    h("div", { class: "item-head" },
      h("strong", {}, c.conflict_type.split("_").join(" ")),
      h("span", { class: "pill red" }, "needs decision")
