.item-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.item-head button {
  width: auto;
  flex: 0 0 auto;
}

.conflict-card > p {
  margin: 8px 0;
}

.conflict-tasks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  margin: 10px 0;
}

.mini-card {
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 10px;
  background: var(--surface-2);
}

.mini-card strong {
  display: block;
  margin: 4px 0;
}

.compact-list {
  margin: 8px 0;
  padding-left: 22px;
}

.compact-list li { margin: 3px 0; }

.error { color: var(--red); }

.login {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 18px;
}

.login-panel {
  width: min(440px, 100%);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.login-panel h1 {
  margin: 0;
  font-family: "Iowan Old Style", "Charter", Georgia, serif;
  font-size: 34px;
  font-weight: 650;
}

.toast {
  position: fixed;
  left: 18px;
  right: 18px;
  bottom: 18px;
  z-index: 50;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 13px;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.check {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 8px;
  background: var(--surface-2);
}

.check input { width: auto; }

hr {
  width: 100%;
  border: 0;
  border-top: 1px solid var(--line);
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes liftIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 1200px) {
  .toolbar.filters {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .toolbar.filters label {
    grid-column: 1 / -1;
  }

  .board {
    grid-template-columns: repeat(7, minmax(220px, 260px));
  }
}

@media (max-width: 900px) {
  .topbar {
    position: static;
    grid-template-columns: 1fr;
    align-items: start;
  }

  .tabs {
    justify-content: flex-start;
  }

  .identity {
    white-space: normal;
  }

  .stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid2 {
    grid-template-columns: 1fr;
  }

  .conflict-tasks {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  body { font-size: 13px; }

  .main { padding: 12px; }

  .toolbar,
  .toolbar.filters {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .toolbar {
    display: grid;
  }

  .stats {
    grid-template-columns: 1fr;
  }

  .row {
    grid-template-columns: 1fr;
  }

  .board {
    grid-template-columns: repeat(7, minmax(238px, 82vw));
  }

  .item-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .button-row {
    align-items: stretch;
  }

  .button-row button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .001ms !important;
  }
}

