  grid-template-columns: 64px minmax(240px, 1.4fr) repeat(3, minmax(140px, 1fr));
  align-items: center;
}

.toolbar.filters input,
.toolbar.filters select {
  min-width: 0;
  max-width: none;
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(130px, 1fr));
  gap: 24px;
}

.stat {
  min-height: 106px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  background: var(--card);
  box-shadow: var(--shadow);
}

.stat strong {
  display: block;
  color: var(--text);
  font-size: 34px;
  font-weight: 800;
  line-height: 1;
}

.stat span {
  display: block;
  margin-top: 10px;
  color: var(--secondary);
  font-size: 14px;
  font-weight: 500;
}

.board {
  display: grid;
  grid-template-columns: repeat(7, minmax(230px, 1fr));
  gap: 24px;
  max-width: 100%;
  min-width: 0;
  overflow-x: auto;
  padding-bottom: 8px;
  overscroll-behavior-x: contain;
}

.column {
  min-height: 460px;
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: var(--shadow);
}

.column h3 {
  margin: 0 0 16px;
  color: var(--text);
  font-size: 18px;
  font-weight: 700;
  text-transform: capitalize;
}

.card {
  min-height: 48px;
  margin: 0;
  padding: 14px 0;
  border: 0;
  border-bottom: 1px solid var(--divider);
  border-radius: 0;
  background: transparent;
  cursor: pointer;
  box-shadow: none;
  transition: background .16s var(--ease);
}

.card:last-child {
  border-bottom: 0;
}

.card:hover {
  margin-inline: -10px;
  padding-inline: 10px;
  border-radius: 12px;
  background: var(--hover);
}

.card-title {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 7px;
  color: var(--text);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}

.task-card.completed .card-title {
  color: var(--secondary);
  text-decoration: line-through;
}

.task-card.completed .card-title::before {
  content: "✓";
  display: grid;
  place-items: center;
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  border-radius: 999px;

