  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 12px;
  background: #FFFFFF;
}

.edit-task summary {
  margin-bottom: 12px;
}

.edit-task:not([open]) summary {
  margin-bottom: 0;
}

details {
  border-radius: var(--radius-sm);
}

summary {
  cursor: pointer;
  color: var(--text);
  font-weight: 600;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(26, 26, 26, .28);
  backdrop-filter: blur(8px);
  animation: fadeIn .16s var(--ease);
}

.modal-card {
  width: min(660px, 100%);
  max-height: calc(100vh - 40px);
  overflow: auto;
  display: grid;
  gap: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  background: var(--card);
  box-shadow: 0 24px 80px rgba(0, 0, 0, .16);
  animation: liftIn .18s var(--ease);
}

.modal-card h2 {
  margin: 0 0 4px;
  font-size: 18px;
  font-weight: 700;
}

.modal-card label {
  color: var(--secondary);
  font-size: 14px;
  font-weight: 500;
}

.modal-card textarea {
  min-height: 104px;
}

.modal-actions {
  justify-content: flex-end;
}

.button-row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  min-width: 0;
}

.button-row button {
  width: auto;
  max-width: 100%;
  white-space: normal;
}

.snapshot-list,
.timeline,
.list {
  display: grid;
  gap: 0;
}

.log-panel {
  max-height: 320px;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: #FFFFFF;
}

.event {
  min-height: 48px;
  display: flex;
  align-items: center;
  padding: 0 14px;
  border-bottom: 1px solid var(--divider);
  color: var(--meta);
  font-size: 13px;
}

.log-line {
  font-family: "SFMono-Regular", Menlo, Consolas, monospace;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.event:last-child {
  border-bottom: 0;
}

.item {
  min-height: 48px;
  border: 0;
  border-bottom: 1px solid var(--divider);
  border-radius: 0;
  padding: 14px 0;
  background: transparent;
  box-shadow: none;
  min-width: 0;
}

.item:last-child {
  border-bottom: 0;
}

.clickable,
.linkish {
  cursor: pointer;
}

.clickable {
  transition: background .16s var(--ease);
}

.clickable:hover {
  margin-inline: -10px;
  padding-inline: 10px;
  border-radius: 12px;
  background: var(--hover);
}

.linkish {
  color: var(--text);
  font-weight: 600;
}

.item-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
  flex-wrap: wrap;
}

.item-head button {
  width: auto;
  flex: 0 0 auto;
}

.item-head>*,
.card,
.panel,
.mini-card,
.task-memory,
.meta,
.card-title {
  min-width: 0;
}

.meta,
.item p,
.mini-card p,
.card-title,
.panel p,
.panel li {
  overflow-wrap: anywhere;
}

.conflict-card>p {
  margin: 8px 0;
}

.conflict-tasks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin: 12px 0;
}

.mini-card {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 14px;
  background: #FFFFFF;
}

.mini-card strong {
  display: block;
  margin: 4px 0;
}

.compact-list {
  margin: 8px 0;
  padding-left: 22px;
}

.compact-list li {
  margin: 4px 0;
}

.error {
  color: var(--danger);
}

.login {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 28px;
}

.login-panel {
  width: min(440px, 100%);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--card);
  box-shadow: var(--shadow);
}

.login-panel h1 {
  margin: 0;
  font-size: 24px;
  font-weight: 800;
}

.toast {
  position: fixed;
  left: 28px;
  right: 28px;
  bottom: 28px;
  z-index: 50;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 18px;
  background: var(--card);
  box-shadow: var(--shadow);
}

.check {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  background: #FFFFFF;
}

.check input {
  width: auto;
}

hr {
  width: 100%;
  border: 0;
  border-top: 1px solid var(--divider);
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes liftIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 1280px) {
  .stats {
    grid-template-columns: repeat(3, minmax(130px, 1fr));
  }

  .toolbar.filters {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .toolbar.filters label {
    grid-column: 1 / -1;
  }

  .board {
    grid-template-columns: repeat(7, minmax(180px, 220px));
  }
}

@media (max-width: 980px) {
  .shell {
    grid-template-columns: 1fr;
    min-height: 100vh;
  }

  .topbar {
    position: static;
    height: auto;
    padding: 18px;
    border-right: 0;
    border-bottom: 1px solid var(--border);
  }

  .tabs {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .tabs button {
    border-radius: 14px;
  }

  .tabs button::before {
    top: auto;
    right: 12px;
    bottom: 0;
    left: 12px;
    width: auto;
    height: 4px;
  }

  .identity {
    margin-top: 0;
  }

  .grid2 {
    grid-template-columns: 1fr;
  }

  .conflict-tasks {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 680px) {
  body {
    font-size: 13px;
  }

  .main {
    padding: 18px;
  }

  .tabs {
    grid-template-columns: 1fr 1fr;
  }

  .toolbar,
  .toolbar.filters {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .toolbar.filters input {
    grid-column: span 1;
  }

  .toolbar {
    display: grid;
  }

  .stats {
    grid-template-columns: 1fr;
  }

  .row {
    grid-template-columns: 1fr;
  }

  .board {
    grid-template-columns: repeat(7, minmax(220px, 82vw));
  }

  .item-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .button-row {
    align-items: stretch;
  }

  .button-row button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .001ms !important;
  }
}

